                                "  \"policy_version\": \"internal-discovery-policy-7\",\n",
                                "  \"policy_sha256\": \"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\",\n",
                                "  \"applicability\": \"APPLICABLE\",\n",
