                                "    \"case_results\": case_results,\n",
                                "    \"outcome\": outcome,\n",
                                "    \"reasons\": reasons,\n",
                                "    \"generated_at\": now.isoformat(),\n",
                                "    \"expires_at\": expires_at.isoformat() if expires_at else None,\n",
                                "}\n",
                                "OUTPUT.parent.mkdir(parents=True, exist_ok=True)\n",
                                "OUTPUT.write_text(\n",
                                "    json.dumps(\n",
                                "        verification,\n",
                                "        sort_keys=True,\n",
                                "        separators=(\",\", \":\"),\n",
                                "        allow_nan=False,\n",
                                "    )\n",
